#include "generalization_data.hpp"
#include "paired_ridge.hpp"
#include <iostream>
using namespace semes;
int wmain(int argc,wchar_t** wide){Utf8Arguments args(argc,wide);auto argv=args.data();try{
    if(argc!=3)throw std::runtime_error("paired_screen copied-reference-root new-output");GeneralizationData data(fs::u8path(argv[1]));auto bank=data.features();fs::path out=fs::u8path(argv[2]);if(fs::exists(out))throw std::runtime_error("New output required");fs::create_directories(out);int n=int(data.manifest.rows.size());cv::Mat truth(n,2,CV_64F);std::vector<std::string> dates;for(int i=0;i<n;++i){truth.at<double>(i,0)=data.manifest.number(i,"Y");truth.at<double>(i,1)=data.manifest.number(i,"T");dates.push_back(data.manifest.text(i,"dataset"));}
    std::ofstream summary(out/"paired_summary.csv"),predictions(out/"paired_predictions.csv");summary<<"candidate,subset,feature,alpha,pair_weight,repeat_weight,n,failures,passed,Y_MAE,Y_max,T_MAE,T_max\n";summary<<std::setprecision(17);predictions<<"index,dataset,file,Y,T,scope,condition,fold,candidate,predY,predT\n";predictions<<std::setprecision(17);Json configs=Json::list();int candidate=0;
    for(std::string feature:{"P12","raw1260","raw_shift"})for(double alpha:{.0001,.01,1.})for(auto weights:{std::pair<double,double>{0,0},{1,0},{10,0},{1,1},{1,10},{10,10}}){
        const auto& X=bank.at(feature);cv::Mat prediction(n,2,CV_64F,cv::Scalar(std::numeric_limits<double>::quiet_NaN()));for(int fold=0;fold<4;++fold){std::vector<int> train,test;std::vector<std::string> training_dates;for(int i=0;i<n;++i){if(int(data.manifest.number(i,"fold"))==fold)test.push_back(i);else{train.push_back(i);training_dates.push_back(dates[i]);}}PairedRidge model(alpha,weights.first,weights.second);model.fit(numeric::rows(X,train),numeric::rows(truth,train),training_dates);auto p=model.predict(numeric::rows(X,test));for(int i=0;i<p.rows;++i)p.row(i).copyTo(prediction.row(test[i]));}
        Json config=Json::dict();config["feature"]=feature;config["alpha"]=alpha;config["pair_weight"]=weights.first;config["repeat_weight"]=weights.second;configs.push(config);
        for(std::string subset:{"new60","old281","all341"}){std::vector<int> rows;for(int i=0;i<n;++i)if(subset=="all341"||(subset=="new60"&&dates[i]=="20261020")||(subset=="old281"&&dates[i]!="20261020"))rows.push_back(i);auto metric=tolerance_metrics(numeric::rows(truth,rows),numeric::rows(prediction,rows));summary<<candidate<<','<<subset<<','<<feature<<','<<alpha<<','<<weights.first<<','<<weights.second;for(auto key:{"n","failures","passed","Y_MAE","Y_max","T_MAE","T_max"})summary<<','<<metric.at(key).dump();summary<<'\n';}
        for(int i=0;i<n;++i){int field=0;for(auto key:{"index","dataset","file","Y","T","scope","condition","fold"})predictions<<(field++?",":"")<<csv(data.manifest.text(i,key));predictions<<','<<candidate<<','<<prediction.at<double>(i,0)<<','<<prediction.at<double>(i,1)<<'\n';}summary.flush();predictions.flush();if(candidate%9==0)std::cout<<candidate<<"/54"<<std::endl;++candidate;
    }
    Json protocol=Json::dict();protocol["configs"]=configs;protocol["folds"]="same previous grouped4fold; newcenter3 together";protocol["training"]="sameT/sameY pair graph and within-command repeat graph computed only from training labels";protocol["inference"]="coordinate features only";protocol["scope"]="development screen";write(out/"paired_protocol.json",protocol.dump());Json check=Json::dict();check["candidates"]=candidate;check["fold_fits"]=candidate*4;check["prediction_rows"]=candidate*n;check["summary_rows"]=candidate*3;check["python_invocations"]=0;write(out/"checks.json",check.dump());return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
